import { useEffect, useId, useState } from "react";
import { api } from "../api";
import { APP_NAME } from "../app/brand";
import { checkForUpdates, updateNow, useUpdateState, type UpdateStatus } from "../app/UpdateNotice";
import { Dialog } from "../ui/Dialog";
import { getAutoCheck, setAutoCheck } from "./updatePref";
// Bundled as text: the CSP blocks fetching it. Generated by scripts/notices.sh.
import NOTICES from "../about/THIRD-PARTY-NOTICES.txt?raw";

function statusText(s: UpdateStatus): string | null {
  switch (s.kind) {
    case "idle":
      return null;
    case "checking":
      return "Checking for updates…";
    case "upToDate":
      return `${APP_NAME} is up to date.`;
    case "failed":
      return "Couldn't check for updates.";
    case "available":
      return `Version ${s.info.version} is available`;
    case "installing":
      return s.pct === null ? "Downloading the update…" : `Downloading the update… ${s.pct}%`;
    case "installFailed":
      return "Couldn't install the update.";
  }
}

/** Desktop only: check now, install what it found, and the after-unlock check's switch. */
function UpdateControls() {
  const { status } = useUpdateState();
  const [auto, setAuto] = useState(getAutoCheck);
  const autoId = useId();
  const busy = status.kind === "checking" || status.kind === "installing";
  const text = statusText(status);
  return (
    <>
      <div className="field">
        <div className="row">
          <button type="button" disabled={busy} onClick={() => void checkForUpdates()}>
            Check for updates
          </button>
          {(status.kind === "available" || status.kind === "installFailed") && (
            <button type="button" className="primary" onClick={() => void updateNow()}>
              Update now
            </button>
          )}
        </div>
        {text && (
          <p role="status" className="muted small">
            {text}
          </p>
        )}
      </div>
      <div className="field">
        <label className="choice" htmlFor={autoId}>
          <input
            id={autoId}
            type="checkbox"
            checked={auto}
            onChange={(e) => {
              setAutoCheck(e.target.checked);
              setAuto(e.target.checked);
            }}
          />
          <span>Automatically check for updates</span>
        </label>
      </div>
    </>
  );
}

/** Settings → About: the app version, updates (desktop) and the third-party license notices. */
export function AboutSettings() {
  const [version, setVersion] = useState<string | null>(null);
  const [showLicenses, setShowLicenses] = useState(false);

  useEffect(() => {
    let live = true;
    api.app.version().then((v) => live && setVersion(v), () => {});
    return () => {
      live = false;
    };
  }, []);

  return (
    <>
      <section className="form settings-form" aria-labelledby="about-settings-title">
        <h2 id="about-settings-title">About</h2>
        <div className="field">
          <p>{version === null ? APP_NAME : `${APP_NAME} ${version}`}</p>
        </div>
        {api.updates.supported && <UpdateControls />}
        <div className="field">
          <div className="row">
            <button type="button" onClick={() => setShowLicenses(true)}>
              Third-party licenses
            </button>
          </div>
        </div>
      </section>
      {showLicenses && (
        <Dialog title="Third-party licenses" wide onClose={() => setShowLicenses(false)}>
          <pre className="mono small licenses-text">{NOTICES}</pre>
          <div className="dialog-actions">
            <button type="button" className="primary" onClick={() => setShowLicenses(false)}>
              Close
            </button>
          </div>
        </Dialog>
      )}
    </>
  );
}
